import {chromium} from 'playwright';
import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
const published=process.env.UI_PUBLISHED==='1', out=`artifacts/anti-slop/${published?'published':'implemented'}/behavior`;
fs.mkdirSync(out,{recursive:true});
const browser=await chromium.launch(), results=[], errors=[], writes=[];
async function setup(route,viewport={width:1440,height:900},scripts=false,shared=false){
 const context=await browser.newContext({viewport,ignoreHTTPSErrors:true,serviceWorkers:'block',permissions:['clipboard-read','clipboard-write']});
 await context.route('**/*',async r=>{
  const u=new URL(r.request().url());
  if(u.hostname!=='preview.saturnity.site') return r.abort();
  const p=u.pathname;
  if(p.startsWith('/api/')){
   if(r.request().method()!=='GET')writes.push({path:p,method:r.request().method()});
   let data=p==='/api/me'&&!shared?{username:'synthetic-ui-test'}:p==='/api/health'?{ok:true,needsSetup:false}:p==='/api/vault'&&!shared?{revision:0,vault:[]}:null;
   if(scripts){
    const script={id:'synthetic-script',name:'fixture.lua',content:'-- synthetic only\nprint("fixture")',updatedAt:'2026-09-01T00:00:00Z',foolShared:true,tokenCount:1};
    if(p==='/api/private-scripts')data={scripts:[script]};
    if(p==='/api/private-scripts/synthetic-script')data={script};
    if(p==='/api/private-scripts/synthetic-script/tokens')data={tokens:[{id:'synthetic-token',createdAt:script.updatedAt}]};
   }
   return r.fulfill({status:data?200:503,contentType:'application/json',body:JSON.stringify(data||{error:'Synthetic unavailable state; private API blocked'})});
  }
  if(published)return r.continue();
  const file=p.startsWith('/assets/')?p.slice(1):p==='/favicon.ico'?'favicon.ico':p.startsWith('/adopt-me')?'adopt-me.html':p.startsWith('/redfinger')?'redfinger.html':'index.html';
  assert(!file.includes('..'));return r.fulfill({contentType:({'.html':'text/html','.css':'text/css','.js':'application/javascript','.svg':'image/svg+xml','.png':'image/png','.jpg':'image/jpeg'})[path.extname(file)]||'application/octet-stream',body:fs.readFileSync(file)});
 });
 const page=await context.newPage();page.on('pageerror',e=>errors.push(e.stack));page.setDefaultTimeout(8000);
 await page.goto('https://preview.saturnity.site'+route);await page.waitForTimeout(350);
 return {page,context};
}
async function setupLoginGate(viewport={width:390,height:844}){
 const context=await browser.newContext({viewport,ignoreHTTPSErrors:true,serviceWorkers:'block'});
 await context.route('**/*',async r=>{
  const u=new URL(r.request().url());
  if(u.hostname!=='preview.saturnity.site') return r.abort();
  const p=u.pathname;
  if(p.startsWith('/api/')){
   const data=p==='/api/health'?{ok:true,needsSetup:false}:p==='/api/me'?{error:'Authentication required'}:p==='/api/vault'?{revision:0,vault:[]}:null;
   return r.fulfill({status:p==='/api/me'?401:(data?200:503),contentType:'application/json',body:JSON.stringify(data||{error:'Synthetic unavailable state; private API blocked'})});
  }
  if(published)return r.continue();
  const file=p.startsWith('/assets/')?p.slice(1):p==='/favicon.ico'?'favicon.ico':p.startsWith('/adopt-me')?'adopt-me.html':p.startsWith('/redfinger')?'redfinger.html':'index.html';
  assert(!file.includes('..'));return r.fulfill({contentType:({'.html':'text/html','.css':'text/css','.js':'application/javascript','.svg':'image/svg+xml','.png':'image/png','.jpg':'image/jpeg'})[path.extname(file)]||'application/octet-stream',body:fs.readFileSync(file)});
 });
 const page=await context.newPage();page.on('pageerror',e=>errors.push(e.stack));page.setDefaultTimeout(8000);
 await page.goto('https://preview.saturnity.site/');await page.waitForTimeout(350);
 return {page,context};
}
async function test(name,fn){try{await fn();results.push({name,status:'passed'});}catch(e){results.push({name,status:'failed',error:e.stack});}fs.writeFileSync(`${out}/summary.json`,JSON.stringify({results,errors,writes},null,2));}
async function clip(page,selector,expected){await page.click(selector);await page.waitForTimeout(120);const actual=await page.evaluate(()=>navigator.clipboard.readText());assert.equal(actual,process.platform==='win32'?expected.replace(/\n/g,'\r\n'):expected);}
async function download(page,selector){const promise=page.waitForEvent('download');await page.click(selector);const d=await promise;const dest=`${out}/${d.suggestedFilename()}`;await d.saveAs(dest);return fs.readFileSync(dest,'utf8');}
